import unreal
m=unreal.load_asset('/Game/TLOU2/Materials/Exact/M_ND_jacket'); tex=unreal.load_asset('/Game/TLOU2/TexturesDecoded/ellie-patrol-jacket-color'); unreal.log('BEFORE '+str(unreal.MaterialEditingLibrary.get_material_expressions(m))+' tex='+str(tex))
